use std::fs

struct Bst {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Bst {
    fn height_at(self, i: int) -> int {
        if i < 0 {
            return 0
        }
        let l = self.height_at(self.lefts[i as usize])
        let r = self.height_at(self.rights[i as usize])
        if l > r { l + 1 } else { r + 1 }
    }

    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur as usize]
            } else {
                cur = self.rights[cur as usize]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) {
            return false
        }
        let idx = self.keys.len() as int
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root < 0 {
            self.root = idx
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.lefts[cur as usize]
                if l < 0 {
                    self.lefts[cur as usize] = idx
                    break
                }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r < 0 {
                    self.rights[cur as usize] = idx
                    break
                }
                cur = r
            }
        }
        true
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent < 0 {
            self.root = new
        } else if self.lefts[parent as usize] == old {
            self.lefts[parent as usize] = new
        } else {
            self.rights[parent as usize] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                cur = self.lefts[cur as usize]
            } else {
                cur = self.rights[cur as usize]
            }
        }
        if cur < 0 {
            return false
        }
        let l = self.lefts[cur as usize]
        let r = self.rights[cur as usize]
        if l >= 0 && r >= 0 {
            let mut sp = cur
            let mut s = r
            while self.lefts[s as usize] >= 0 {
                sp = s
                s = self.lefts[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.rights[s as usize]
            self.replace_child(sp, s, sr)
        } else if l >= 0 {
            self.replace_child(parent, cur, l)
        } else {
            self.replace_child(parent, cur, r)
        }
        true
    }

    fn inorder(self) -> string {
        let mut out = ""
        let mut stack: Vec<int> = []
        let mut cur = self.root
        let mut first = true
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.lefts[cur as usize]
            }
            let n = stack.pop() ?? 0
            if !first {
                out = out + " "
            }
            first = false
            out = out + "${self.keys[n as usize]}"
            cur = self.rights[n as usize]
        }
        if first { "<empty>" } else { out }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Bst { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts = line.trim().split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height_at(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.lefts[c as usize] >= 0 { c = t.lefts[c as usize] }
                } else {
                    while t.rights[c as usize] >= 0 { c = t.rights[c as usize] }
                }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

